// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, address target, bool emergency) public {
        // Ensure sender has the needed flash governance asset and approval
        vm.assume(sender != address(0) && target != address(0));

        // Try to call assertGovernanceApproved - may revert
        (bool success, ) = address(c).call(
            abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", sender, target, emergency)
        );

        // The general rule: regardless of success or failure, DAO must remain address(this)
        assertTrue(c.DAO() == address(this));
    }
}

